revert("userMaxTypeOf");
}
uint256 culDays = (block.timestamp - raceCarStartTime) / 1 days;
userRaceCarDayCount[user][culDays] += 1;
if(userRaceCarDayCount[user][culDays] > raceCarMaxCount) {
revert("userRaceCarDayCount");
